"""Runs the real Whisper model on speech generated by macOS text-to-speech.

Run with: .venv/bin/python -m pytest -m integration
Needs macOS, the `say` command and the model already in the Hugging Face cache.
"""

import shutil
import subprocess
import sys
import wave
from pathlib import Path
from unittest import mock

import numpy as np
import pytest

from tests.conftest import load_bisik, make_quartz

MODEL = "mlx-community/whisper-large-v3-turbo"
MODEL_CACHE = Path.home() / ".cache/huggingface/hub/models--mlx-community--whisper-large-v3-turbo"

pytestmark = [
    pytest.mark.integration,
    pytest.mark.skipif(sys.platform != "darwin" or shutil.which("say") is None, reason="needs macOS text-to-speech"),
    pytest.mark.skipif(not MODEL_CACHE.exists(), reason="Whisper model is not downloaded yet"),
]


def voices():
    listing = subprocess.run(["say", "-v", "?"], capture_output=True, text=True, check=True).stdout
    return {line.split()[0] for line in listing.splitlines() if line.strip()}


def speak(tmp_path, voice, text):
    """Return 16 kHz mono float32 audio of `text`, the format Bisik records."""
    path = tmp_path / "speech.wav"
    subprocess.run(["say", "-v", voice, "-o", str(path), "--data-format=LEI16@16000", text], check=True)
    with wave.open(str(path)) as wav:
        assert wav.getframerate() == 16000
        frames = wav.readframes(wav.getnframes())
    return np.frombuffer(frames, dtype=np.int16).astype("float32") / 32768.0


@pytest.fixture(scope="module")
def whisper():
    import mlx_whisper

    return mlx_whisper


@pytest.fixture
def bisik(monkeypatch):
    # Only macOS key events are replaced, the model and numpy are real.
    return load_bisik(monkeypatch, Quartz=make_quartz(), sounddevice=mock.MagicMock())


CASES = [
    pytest.param(
        "Samantha",
        "Hello, this is a test of the dictation app.",
        "en",
        ["hello", "test", "dictation"],
        id="english",
    ),
    pytest.param(
        "Damayanti",
        "Selamat pagi, ini adalah percobaan aplikasi dikte suara.",
        "id",
        ["selamat pagi", "percobaan", "aplikasi"],
        id="indonesian",
    ),
]


@pytest.mark.parametrize(("voice", "sentence", "language", "keywords"), CASES)
class TestRealTranscription:
    def test_model_detects_the_language_and_hears_the_words(
        self, whisper, tmp_path, voice, sentence, language, keywords
    ):
        if voice not in voices():
            pytest.skip(f"voice {voice} is not installed")
        audio = speak(tmp_path, voice, sentence)

        result = whisper.transcribe(audio, path_or_hf_repo=MODEL)

        text = result["text"].lower()
        assert result["language"] == language
        missing = [word for word in keywords if word not in text]
        assert not missing, f"missing {missing} in {text!r}"

    def test_bisik_pipeline_copies_and_pastes_the_transcript(
        self, bisik, tmp_path, capsys, voice, sentence, language, keywords
    ):
        if voice not in voices():
            pytest.skip(f"voice {voice} is not installed")
        audio = speak(tmp_path, voice, sentence)

        with mock.patch.object(bisik.subprocess, "run") as run, mock.patch.object(bisik, "paste") as paste:
            bisik.transcribe_and_paste(audio)

        run.assert_called_once()
        assert run.call_args.args[0] == ["pbcopy"]
        copied = run.call_args.kwargs["input"].decode().lower()
        assert all(word in copied for word in keywords), copied
        paste.assert_called_once()
        assert f"[{language}]" in capsys.readouterr().out


def noise(level):
    return np.random.default_rng(0).normal(0, level, 32000).astype("float32")


@pytest.mark.parametrize(
    "audio",
    [
        pytest.param(np.zeros(32000, dtype="float32"), id="digital-silence"),
        pytest.param(noise(0.001), id="very-quiet-room"),
        pytest.param(noise(0.005), id="quiet-room"),
    ],
)
def test_silence_and_room_noise_are_never_pasted(bisik, audio):
    """Regression: the real model answers "Thank you." to silence, which must not be pasted."""
    with mock.patch.object(bisik.subprocess, "run") as run, mock.patch.object(bisik, "paste") as paste:
        bisik.transcribe_and_paste(audio)
    run.assert_not_called()
    paste.assert_not_called()


@pytest.mark.parametrize("gain", [0.05, 0.01], ids=["quiet-speech", "whisper"])
def test_quiet_speech_is_still_transcribed(bisik, tmp_path, gain):
    if "Samantha" not in voices():
        pytest.skip("voice Samantha is not installed")
    audio = speak(tmp_path, "Samantha", "Hello, this is a test of the dictation app.") * gain

    with mock.patch.object(bisik.subprocess, "run") as run, mock.patch.object(bisik, "paste") as paste:
        bisik.transcribe_and_paste(audio)

    paste.assert_called_once()
    copied = run.call_args.kwargs["input"].decode().lower()
    assert "hello" in copied
    assert "dictation" in copied
